    symptom: { ko: 'app.txt 를 엉망으로 고쳤고 README.md 를 실수로 지웠습니다. 둘 다 마지막 커밋의 상태로 되돌리세요.', en: 'You messed up app.txt and deleted README.md by accident. Restore both to the last commit.' },
